48	static void ComputeTiling(MoeGatingTopKSoftmaxV2Tiling* t,
49	                          int64_t B, int64_t N, int64_t k,
50	                          int64_t renorm, int64_t hasFinished,
51	                          int64_t dtypeFlag)
52	{
53	    std::memset(t, 0, sizeof(MoeGatingTopKSoftmaxV2Tiling));
54	    t->B = B;
55	    t->N = N;
56	    t->k = k;
57	    t->renorm = renorm;
58	    t->hasFinished = hasFinished;
59	    t->dtypeFlag = dtypeFlag;
60	
61	    // Sort-aligned N
62	    int64_t sortN = ((N + ONE_REPEAT_SORT_NUM - 1) / ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;
63	    t->sortN = sortN;
64	
65	    // Determine fullload vs tiled
66	    if (N <= UB_FULLLOAD_CAPACITY) {
67	        t->useTiled = 0;
68	    } else {
69	        t->useTiled = 1;
70	    }
71	
72	    // Block-level tiling: split B rows across cores
73	    int64_t coreNum = std::min<int64_t>(NUM_PHYSICAL_CORES, B);
74	    t->coreNum = coreNum;
75	    t->rowsPerCore = (B + coreNum - 1) / coreNum;
76	
77	    // Tiled path parameters
78	    t->tileSize = TILE_SIZE;
79	    t->numTiles = (N + TILE_SIZE - 1) / TILE_SIZE;
80	    int64_t tileN = ((TILE_SIZE + ONE_REPEAT_SORT_NUM - 1) / ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;

