84	std::tuple<at::Tensor, at::Tensor, at::Tensor>
85	moe_gating_topk_softmax_v2(
86	    const at::Tensor& x,
87	    const at::Tensor& finished_optional,
88	    int64_t k,
89	    int64_t renorm)
90	{
91	    // Input validation
92	    TORCH_CHECK(x.dim() == 2, "x must be 2D [B, N]");
93	    TORCH_CHECK(k > 0 && k <= x.size(1), "k must be in (0, N]");
94	    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
95	
96	    int64_t B = x.size(0);
97	    int64_t N = x.size(1);
98	    auto dtype = x.scalar_type();
99	    int64_t dtypeFlag = 0;
100	    if (dtype == at::kHalf) {
101	        dtypeFlag = 1;
102	    } else if (dtype == at::kBFloat16) {
103	        dtypeFlag = 2;
104	    }
105	
106	    bool hasFinished = finished_optional.defined();
107	    int64_t hasFinishedVal = hasFinished ? 1 : 0;
108	
109	    // Output tensors
110	    auto topkOut = at::empty({B, k}, x.options());
111	    auto indicesOut = at::empty({B, k}, x.options().dtype(at::kInt));
112	    auto softmaxOut = at::empty({B, N}, x.options().dtype(at::kFloat));
113	
114	    // Tiling computation
115	    MoeGatingTopKSoftmaxV2Tiling tiling;
116	    ComputeTiling(&tiling, B, N, k, renorm, hasFinishedVal, dtypeFlag);
117	
118	    // Copy tiling struct to device memory
119	    at::Tensor tilingCpu = at::empty(
120	        {static_cast<int64_t>(sizeof(MoeGatingTopKSoftmaxV2Tiling))},
121	        at::device(at::kCPU).dtype(at::kByte));
122	    std::memcpy(tilingCpu.data_ptr(), &tiling, sizeof(MoeGatingTopKSoftmaxV2Tiling));
123	    at::Tensor tilingNpu = tilingCpu.to(at::kPrivateUse1);
124	
125	    // Workspace is not needed for this pure-vector kernel
126	    at::Tensor workspace = at::empty({0}, x.options().dtype(at::kByte));
127	
128	    // Prepare finished_optional (int8 on device)
129	    at::Tensor finishedTensor;
130	    if (hasFinished) {
131	        finishedTensor = finished_optional.to(at::kByte).contiguous();
132	    } else {
133	        finishedTensor = at::zeros({B}, at::device(at::kPrivateUse1).dtype(at::kByte));
134	    }
135	
136	    // EXEC_KERNEL_CMD requires all lvalue parameters
137	    uint32_t blockDim = static_cast<uint32_t>(tiling.coreNum);
138	
139	    if (tiling.useTiled == 0) {
140	        // Fullload path
141	        if (dtype == at::kFloat) {
142	            EXEC_KERNEL_CMD(moe_gating_topk_softmax_v2_fullload_fp32, blockDim,
143	                x, finishedTensor, topkOut, indicesOut, softmaxOut, tilingNpu, workspace);
144	        } else if (dtype == at::kHalf) {
145	            EXEC_KERNEL_CMD(moe_gating_topk_softmax_v2_fullload_fp16, blockDim,
146	                x, finishedTensor, topkOut, indicesOut, softmaxOut, tilingNpu, workspace);
147	        } else {  // bf16
148	            EXEC_KERNEL_CMD(moe_gating_topk_softmax_v2_fullload_bf16, blockDim,
149	                x, finishedTensor, topkOut, indicesOut, softmaxOut, tilingNpu, workspace);
150	        }
151	    } else {
152	        // Tiled path
153	        if (dtype == at::kFloat) {
154	            EXEC_KERNEL_CMD(moe_gating_topk_softmax_v2_tiled_fp32, blockDim,
155	                x, finishedTensor, topkOut, indicesOut, softmaxOut, tilingNpu, workspace);
156	        } else if (dtype == at::kHalf) {
157	            EXEC_KERNEL_CMD(moe_gating_topk_softmax_v2_tiled_fp16, blockDim,
158	                x, finishedTensor, topkOut, indicesOut, softmaxOut, tilingNpu, workspace);
159	        } else {  // bf16
160	            EXEC_KERNEL_CMD(moe_gating_topk_softmax_v2_tiled_bf16, blockDim,
161	                x, finishedTensor, topkOut, indicesOut, softmaxOut, tilingNpu, workspace);
162	        }
163	    }
164	
165	    return std::make_tuple(topkOut, indicesOut, softmaxOut);
166	}
