84	template <typename T>
85	__aicore__ inline void KernelFullload<T>::Init(
86	    GM_ADDR x, GM_ADDR finished, GM_ADDR topk,
87	    GM_ADDR indices, GM_ADDR softmaxOut,
88	    const MoeGatingTopKSoftmaxV2Tiling* tiling, TPipe* tPipe)
89	{
90	    pipe = tPipe;
91	    B = tiling->B; N = tiling->N; k = tiling->k;
92	    renorm = tiling->renorm; hasFinished = tiling->hasFinished;
93	    sortN = tiling->sortN;
94	    int64_t cid = GetBlockIdx();
95	    int64_t rowsPerCore = tiling->rowsPerCore;
96	    coreStart = cid * rowsPerCore;
97	    coreEnd = MinVal64(coreStart + rowsPerCore, B);
98	
99	    xGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), B * N);
100	    finGm.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t*>(finished), B);
101	    topkGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(topk), B * k);
102	    idxGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(indices), B * k);
103	    smGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(softmaxOut), B * N);
104	
105	    // qIn: need to handle both T input + int8 finished flag, size for max
106	    int64_t qInBytes = sizeof(T) * sortN + sizeof(int8_t) * 4 + BLOCK_BYTES;
107	    pipe->InitBuffer(qIn, 1, qInBytes);
108	    // qOut: T topk + int32 indices
109	    int64_t qOutBytes = sizeof(T) * k + sizeof(int32_t) * k + BLOCK_BYTES;
110	    pipe->InitBuffer(qOut, 1, qOutBytes);
111	
112	    // bufA: xFp32[sortN] + expUb[sortN] + smUb[sortN]
113	    pipe->InitBuffer(bufA, sortN * sizeof(float) * 3 + BLOCK_BYTES);
114	    // bufB: redTmp[sortN*2]float + idxUb[sortN]int32
115	    pipe->InitBuffer(bufB, sortN * 2 * sizeof(float) + sortN * sizeof(int32_t) + BLOCK_BYTES);
116	    // bufC: sortTemp[sortN*2]float + sortDst[sortN*2]float + topk+k*2+cast
117	    pipe->InitBuffer(bufC, sortN * 4 * sizeof(float) + k * sizeof(float) * 2 + k * sizeof(int32_t) + BLOCK_BYTES);
118	    // bufD: max+sum+renorm+fin
119	    pipe->InitBuffer(bufD, sizeof(float) * 4 + BLOCK_BYTES);
120	}
