122	template <typename T>
123	__aicore__ inline void KernelFullload<T>::Process()
124	{
125	    if (coreStart >= B) return;
126	    for (int64_t bx = 0; bx < coreEnd - coreStart; ++bx)
127	        ProcessRow(coreStart + bx);
128	}
