130	template <typename T>
131	__aicore__ inline void KernelFullload<T>::ProcessRow(int64_t rowIdx)
132	{
133	    constexpr bool isHalf = (sizeof(T) == 2);
134	
135	    // UB buffers
136	    LocalTensor<float> xFp32  = bufA.Get<float>(0);
137	    LocalTensor<float> expUb  = bufA.Get<float>(sortN * sizeof(float));
138	    LocalTensor<float> smUb   = bufA.Get<float>(sortN * 2 * sizeof(float));
139	
140	    LocalTensor<float> redTmp  = bufB.Get<float>(0);
141	    LocalTensor<int32_t> idxUb = bufB.Get<int32_t>(sortN * 2 * sizeof(float));
142	
143	    LocalTensor<float> sortTemp = bufC.Get<float>(0);
144	    LocalTensor<float> sortDst  = bufC.Get<float>(sortN * 2 * sizeof(float));
145	    int64_t topkOff = sortN * 4 * sizeof(float);
146	    LocalTensor<float> topkV   = bufC.Get<float>(topkOff);
147	    LocalTensor<int32_t> topkI = bufC.Get<int32_t>(topkOff + k * sizeof(float));
148	    LocalTensor<float> castBk  = bufC.Get<float>(topkOff + k * sizeof(float) + k * sizeof(int32_t));
149	
150	    LocalTensor<float> maxU = bufD.Get<float>(0);
151	    LocalTensor<float> sumU = bufD.Get<float>(sizeof(float));
152	    LocalTensor<float> rnU  = bufD.Get<float>(sizeof(float) * 2);
153	
154	    // Step 1: Copy in x[row,:]
155	    LocalTensor<T> xUb = qIn.AllocTensor<T>();
156	    DataCopyExtParams cp{1, static_cast<uint32_t>(N * sizeof(T)), 0, 0, 0};
157	    DataCopyPadExtParams<T> pp{false, 0, 0, 0};
158	    DataCopyPad(xUb, xGm[rowIdx * N], cp, pp);
159	    qIn.EnQue(xUb);
160	    LocalTensor<T> xDq = qIn.DeQue<T>();
161	    if constexpr (isHalf) Cast(xFp32, xDq, RoundMode::CAST_NONE, N);
162	    else DataCopy(xFp32, xDq, N);
163	    qIn.FreeTensor(xDq);
164	
165	    // Step 2: Softmax
166	    ReduceMax<float>(maxU, xFp32, redTmp, sortN);
167	    float mv = maxU.GetValue(0);
168	    Adds(expUb, xFp32, static_cast<float>(-mv), N);
169	    Exp(expUb, expUb, N);
170	    ReduceSum<float>(sumU, expUb, redTmp, sortN);
171	    float sv = sumU.GetValue(0);
172	    Muls(smUb, expUb, 1.0f / (sv + 1e-10f), N);
173	
174	    // Step 3: Write softmax to GM
175	    DataCopyExtParams scp{1, static_cast<uint32_t>(N * sizeof(float)), 0, 0, 0};
176	    DataCopyPad(smGm[rowIdx * N], smUb, scp);
177	
178	    // Step 4: Sort descending
179	    if (N < sortN) Duplicate(smUb[N], MIN_FP32, sortN - N);
180	    CreateVecIndex(idxUb, 0, static_cast<int32_t>(sortN));
181	    int32_t srpt = static_cast<int32_t>(sortN / ONE_REPEAT_SORT_NUM);
182	    LocalTensor<float> concatOut;
183	    Concat(concatOut, smUb, sortTemp, srpt);
184	    LocalTensor<uint32_t> iU32 = idxUb.ReinterpretCast<uint32_t>();
185	    Sort<float, true>(sortDst, concatOut, iU32, sortTemp, srpt);
186	    LocalTensor<float> keys;
187	    LocalTensor<uint32_t> vals32;
188	    Extract(keys, vals32, sortDst, srpt);
189	    LocalTensor<int32_t> vals = vals32.ReinterpretCast<int32_t>();
190	
191	    // Step 5: Top-k
192	    DataCopy(topkV, keys, k);
193	    DataCopy(topkI, vals, k);
194	
195	    // Step 6: Optional renorm
196	    if (renorm) {
197	        ReduceSum<float>(rnU, topkV, redTmp, static_cast<uint32_t>(k));
198	        float rv = rnU.GetValue(0);
199	        Muls(topkV, topkV, 1.0f / (rv + 1e-10f), k);
200	    }
201	
202	    // Step 7: Optional finished mask
203	    if (hasFinished) {
204	        int8_t done = 0;
205	        LocalTensor<int8_t> fUb = qIn.AllocTensor<int8_t>();
206	        DataCopyPadExtParams<int8_t> fpp{false, 0, 0, 0};
207	        DataCopyPad(fUb, finGm[rowIdx], DataCopyExtParams{1, 1, 0, 0, 0}, fpp);
208	        qIn.EnQue(fUb);
209	        LocalTensor<int8_t> fDq = qIn.DeQue<int8_t>();
210	        done = fDq.GetValue(0);
211	        qIn.FreeTensor(fDq);
212	        if (done) Duplicate(topkI, static_cast<int32_t>(N), k);
213	    }
214	
215	    // Step 8: Cast + CopyOut
216	    LocalTensor<T> oT = qOut.AllocTensor<T>();
217	    if constexpr (isHalf) Cast(oT, topkV, RoundMode::CAST_ROUND, k);
218	    else DataCopy(oT, topkV.ReinterpretCast<T>(), k);
219	    qOut.EnQue(oT);
220	    LocalTensor<T> oD = qOut.DeQue<T>();
221	    DataCopyPad(topkGm[rowIdx * k], oD, DataCopyExtParams{1, static_cast<uint32_t>(k * sizeof(T)), 0, 0, 0});
222	    qOut.FreeTensor(oD);
223	
224	    LocalTensor<int32_t> iT = qOut.AllocTensor<int32_t>();
225	    DataCopy(iT, topkI, k);
226	    qOut.EnQue(iT);
227	    LocalTensor<int32_t> iD = qOut.DeQue<int32_t>();
228	    DataCopyPad(idxGm[rowIdx * k], iD, DataCopyExtParams{1, static_cast<uint32_t>(k * sizeof(int32_t)), 0, 0, 0});
229	    qOut.FreeTensor(iD);
230	}
