#include <algorithm>
#include <cstring>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_scaled_masked_softmax_v2_fp32.h"
#include "aclrtlaunch_scaled_masked_softmax_v2_fp16.h"
#include "aclrtlaunch_scaled_masked_softmax_v2_bf16.h"

constexpr int64_t NUM_PHYSICAL_CORES = 28;
constexpr int64_t HEAD_DIM_ALIGN = 32;
constexpr int64_t REDUCE_ALIGN = 64;

struct ScaledMaskedSoftmaxV2Tiling {
    int64_t totalRows;
    int64_t headDim;
    int64_t alignedHd;
    int64_t reduceCount;
    int64_t coreNum;
    int64_t rowsPerCore;
    float scale;
};

namespace ascend_kernel {

static void ComputeTiling(ScaledMaskedSoftmaxV2Tiling* t,
                          int64_t totalRows, int64_t headDim, float scale)
{
    std::memset(t, 0, sizeof(ScaledMaskedSoftmaxV2Tiling));
    t->totalRows = totalRows;
    t->headDim = headDim;
    t->scale = scale;

    // Align head_dim to 32 for vector operations
    int64_t alignedHd = ((headDim + HEAD_DIM_ALIGN - 1) / HEAD_DIM_ALIGN) * HEAD_DIM_ALIGN;
    t->alignedHd = alignedHd;

    // Reduction count aligned to 64
    int64_t reduceCount = ((alignedHd + REDUCE_ALIGN - 1) / REDUCE_ALIGN) * REDUCE_ALIGN;
    t->reduceCount = reduceCount;

    // Block-level tiling: split totalRows across cores
    int64_t coreNum = static_cast<int64_t>(std::min<int64_t>(NUM_PHYSICAL_CORES, totalRows));
    t->coreNum = coreNum;
    t->rowsPerCore = (totalRows + coreNum - 1) / coreNum;
}

at::Tensor scaled_masked_softmax_v2(
    const at::Tensor& x,
    const at::Tensor& mask,
    double scale)
{
    // Input validation
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(mask.is_contiguous(), "mask must be contiguous");
    TORCH_CHECK(x.dim() == 2, "x must be 2D [total_rows, head_dim]");
    TORCH_CHECK(mask.dim() == 2, "mask must be 2D [total_rows, head_dim]");
    TORCH_CHECK(mask.scalar_type() == at::kFloat, "mask must be float32");

    int64_t totalRows = x.size(0);
    int64_t headDim = x.size(1);
    auto dtype = x.scalar_type();

    // Output tensor
    auto y = at::empty({totalRows, headDim}, x.options());

    // Tiling computation
    ScaledMaskedSoftmaxV2Tiling tiling;
    ComputeTiling(&tiling, totalRows, headDim, static_cast<float>(scale));

    // Copy tiling struct to device memory
    at::Tensor tilingCpu = at::empty(
        {static_cast<int64_t>(sizeof(ScaledMaskedSoftmaxV2Tiling))},
        at::device(at::kCPU).dtype(at::kByte));
    std::memcpy(tilingCpu.data_ptr(), &tiling, sizeof(ScaledMaskedSoftmaxV2Tiling));
    at::Tensor tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // Workspace (not needed for this kernel)
    at::Tensor workspace = at::empty({0}, x.options().dtype(at::kByte));

    // EXEC_KERNEL_CMD: all parameters must be lvalues
    uint32_t blockDim = static_cast<uint32_t>(tiling.coreNum);

    if (dtype == at::kFloat) {
        EXEC_KERNEL_CMD(scaled_masked_softmax_v2_fp32, blockDim,
            x, mask, y, tilingNpu, workspace);
    } else if (dtype == at::kHalf) {
        EXEC_KERNEL_CMD(scaled_masked_softmax_v2_fp16, blockDim,
            x, mask, y, tilingNpu, workspace);
    } else {  // bfloat16
        EXEC_KERNEL_CMD(scaled_masked_softmax_v2_bf16, blockDim,
            x, mask, y, tilingNpu, workspace);
    }

    return y;
}

}  // namespace ascend_kernel
