127	    LocalTensor<float> smUb   = bufB.Get<float>(alignedHd * sizeof(float) * 3);
128	
129	    LocalTensor<float> redTmp = bufC.Get<float>(0);
130	    LocalTensor<float> maxUb  = bufC.Get<float>(reduceCount * 2 * sizeof(float));
131	    LocalTensor<float> sumUb  = bufC.Get<float>(reduceCount * 2 * sizeof(float) + sizeof(float));
132	
133	    // ---- Step 1: Copy input x[rowIdx, :] from GM to UB ----
134	    LocalTensor<T> xUb = qIn.AllocTensor<T>();
135	    DataCopyExtParams cp{1, static_cast<uint32_t>(headDim * sizeof(T)), 0, 0, 0};
136	    DataCopyPadExtParams<T> pp{false, 0, 0, 0};
137	    DataCopyPad(xUb, xGm[rowIdx * headDim], cp, pp);
138	    qIn.EnQue(xUb);
139	    LocalTensor<T> xDq = qIn.DeQue<T>();
140	
141	    // ---- Step 2: Cast to float32 ----
142	    if constexpr (isHalf) {
143	        Cast(xFp32, xDq, RoundMode::CAST_NONE, headDim);
144	    } else {
145	        DataCopy(xFp32, xDq, headDim);
146	    }
147	    qIn.FreeTensor(xDq);
148	
149	    // ---- Step 3: Multiply by scale ----
150	    if (scale != 1.0f) {
151	        Muls(xFp32, xFp32, scale, headDim);
152	    }
153	
154	    // ---- Step 4: Copy mask[rowIdx, :] from GM to UB (float32, DataCopyPad with 4 args on TBuf) ----
155	    {
156	        DataCopyExtParams mcp{1, static_cast<uint32_t>(headDim * sizeof(float)), 0, 0, 0};
157	        DataCopyPadExtParams<float> mpad{false, 0, 0, 0};
158	        DataCopyPad(maskUb, maskGm[rowIdx * headDim], mcp, mpad);
159	    }
160	
161	    // ---- Step 5: Apply mask ----
162	    // x = x * (1 - mask) + (-10000.0) * mask
163	    // Step 5a: tmp1 = x_fp32 * mask
164	    Mul(tmp1Ub, xFp32, maskUb, headDim);
165	    // Step 5b: x_fp32 = x_fp32 - tmp1 = x_fp32 * (1 - mask)
166	    Sub(xFp32, xFp32, tmp1Ub, headDim);
167	    // Step 5c: tmp1 = (-10000.0) * mask
168	    Muls(tmp1Ub, maskUb, MASK_NEG_INF, headDim);
169	    // Step 5d: x_fp32 = x_fp32 + tmp1
170	    Add(xFp32, xFp32, tmp1Ub, headDim);
171	
172	    // ---- Step 6: Softmax along head_dim ----
173	    // 6a. ReduceMax
174	    ReduceMax<float>(maxUb, xFp32, redTmp, static_cast<uint32_t>(reduceCount));
175	    float maxVal = maxUb.GetValue(0);
176	
177	    // 6b. Subtract max
178	    Adds(subUb, xFp32, static_cast<float>(-maxVal), headDim);
179	
180	    // 6c. Exp
181	    Exp(expUb, subUb, headDim);
182	
183	    // 6d. ReduceSum
184	    ReduceSum<float>(sumUb, expUb, redTmp, static_cast<uint32_t>(reduceCount));
185	    float sumVal = sumUb.GetValue(0);
186	
187	    // 6e. Normalize: softmax = exp / sum(exp), add epsilon to avoid div by zero
188	    Muls(smUb, expUb, 1.0f / (sumVal + 1e-10f), headDim);
189	
190	    // ---- Step 7: Cast softmax to original dtype + CopyOut ----
191	    LocalTensor<T> oT = qOut.AllocTensor<T>();
192	    if constexpr (isHalf) {
193	        Cast(oT, smUb, RoundMode::CAST_ROUND, headDim);
194	    } else {
195	        DataCopy(oT, smUb.ReinterpretCast<T>(), headDim);
196	    }
197	    qOut.EnQue(oT);
198	    LocalTensor<T> oD = qOut.DeQue<T>();
199	    DataCopyExtParams ocp{1, static_cast<uint32_t>(headDim * sizeof(T)), 0, 0, 0};
200	    DataCopyPad(yGm[rowIdx * headDim], oD, ocp);
201	    qOut.FreeTensor(oD);
202	}
