#include "kernel_operator.h"

constexpr int64_t HEAD_DIM_ALIGN = 32;
constexpr int64_t REDUCE_ALIGN_LOG2 = 6;  // 2^6 = 64
constexpr int64_t BLOCK_BYTES = 32;

struct ScaledMaskedSoftmaxV2Tiling {
    int64_t totalRows;
    int64_t headDim;
    int64_t alignedHd;
    int64_t reduceCount;
    int64_t coreNum;
    int64_t rowsPerCore;
    float scale;
};

using namespace AscendC;

__aicore__ inline int64_t CeilDiv(int64_t a, int64_t b) {
    if (b == 0) return 0;
    return (a + b - 1) / b;
}
__aicore__ inline int64_t AlignUp(int64_t n, int64_t align) {
    return ((n + align - 1) / align) * align;
}
__aicore__ inline int64_t MinVal64(int64_t a, int64_t b) { return a < b ? a : b; }

template <typename T>
class KernelScaledMaskedSoftmaxV2 {
public:
    __aicore__ inline KernelScaledMaskedSoftmaxV2() {}
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR mask, GM_ADDR y,
        const ScaledMaskedSoftmaxV2Tiling* tiling, TPipe* tPipe);
    __aicore__ inline void Process();

private:
    __aicore__ inline void ProcessRow(int64_t rowIdx);

    int64_t totalRows, headDim, alignedHd, reduceCount;
    int64_t coreStart, coreEnd;
    float scale;

    TPipe* pipe;
    TQue<QuePosition::VECIN, 1>  qIn;    // for x input (type T)
    TQue<QuePosition::VECIN, 1>  qMask;  // for mask input (type float)
    TQue<QuePosition::VECOUT, 1> qOut;   // for y output (type T)

    GlobalTensor<T>     xGm;
    GlobalTensor<float> maskGm;
    GlobalTensor<T>     yGm;

    TBuf<TPosition::VECCALC> bufA;  // xFp32 + exp
    TBuf<TPosition::VECCALC> bufB;  // mask + tmp1 + sub + softmax
    TBuf<TPosition::VECCALC> bufC;  // reduceTmp + max + sum
};

template <typename T>
__aicore__ inline void KernelScaledMaskedSoftmaxV2<T>::Init(
    GM_ADDR x, GM_ADDR mask, GM_ADDR y,
    const ScaledMaskedSoftmaxV2Tiling* tiling, TPipe* tPipe)
{
    pipe = tPipe;
    totalRows = tiling->totalRows;
    headDim = tiling->headDim;
    alignedHd = tiling->alignedHd;
    reduceCount = tiling->reduceCount;
    scale = tiling->scale;

    int64_t cid = GetBlockIdx();
    int64_t rowsPerCore = tiling->rowsPerCore;
    coreStart = cid * rowsPerCore;
    coreEnd = MinVal64(coreStart + rowsPerCore, totalRows);

    xGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), totalRows * headDim);
    maskGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(mask), totalRows * headDim);
    yGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y), totalRows * headDim);

    // qIn: input x tile (type T)
    int64_t qInBytes = sizeof(T) * alignedHd + BLOCK_BYTES;
    pipe->InitBuffer(qIn, 1, qInBytes);

    // qMask: mask tile (type float, separate queue to avoid type mixing)
    int64_t qMaskBytes = sizeof(float) * alignedHd + BLOCK_BYTES;
    pipe->InitBuffer(qMask, 1, qMaskBytes);

    // qOut: output y tile (type T)
    int64_t qOutBytes = sizeof(T) * alignedHd + BLOCK_BYTES;
    pipe->InitBuffer(qOut, 1, qOutBytes);

    // bufA: xFp32[alignedHd] + exp[alignedHd]
    pipe->InitBuffer(bufA, alignedHd * sizeof(float) * 2 + BLOCK_BYTES);

    // bufB: mask[alignedHd] + tmp1[alignedHd] + sub[alignedHd] + softmax[alignedHd]
    pipe->InitBuffer(bufB, alignedHd * sizeof(float) * 4 + BLOCK_BYTES);

    // bufC: reduceTmp[reduceCount*sizeof(float)] + max[1] + sum[1]
    int64_t redTmpBytes = reduceCount * sizeof(float);
    pipe->InitBuffer(bufC, redTmpBytes + sizeof(float) * 2 + BLOCK_BYTES);
}

template <typename T>
__aicore__ inline void KernelScaledMaskedSoftmaxV2<T>::Process()
{
    if (coreStart >= totalRows) return;
    for (int64_t bx = 0; bx < coreEnd - coreStart; ++bx)
        ProcessRow(coreStart + bx);
}

template <typename T>
__aicore__ inline void KernelScaledMaskedSoftmaxV2<T>::ProcessRow(int64_t rowIdx)
{
    constexpr bool isHalf = (sizeof(T) == 2);

    // UB buffer offsets
    LocalTensor<float> xFp32 = bufA.Get<float>(0);
    LocalTensor<float> expUb = bufA.Get<float>(alignedHd * sizeof(float));

    LocalTensor<float> maskUb = bufB.Get<float>(0);
    LocalTensor<float> tmp1Ub = bufB.Get<float>(alignedHd * sizeof(float));
    LocalTensor<float> subUb  = bufB.Get<float>(alignedHd * sizeof(float) * 2);
    LocalTensor<float> smUb   = bufB.Get<float>(alignedHd * sizeof(float) * 3);

    int64_t redTmpBytes = reduceCount * sizeof(float);
    LocalTensor<float> redTmp = bufC.Get<float>(0);
    LocalTensor<float> maxUb  = bufC.Get<float>(redTmpBytes);
    LocalTensor<float> sumUb  = bufC.Get<float>(redTmpBytes + sizeof(float));

    // ---- Step 1: Copy input x[rowIdx, :] from GM to UB via qIn ----
    LocalTensor<T> xUb = qIn.AllocTensor<T>();
    DataCopyExtParams cp{1, static_cast<uint32_t>(headDim * sizeof(T)), 0, 0, 0};
    DataCopyPadExtParams<T> pp{false, 0, 0, 0};
    DataCopyPad(xUb, xGm[rowIdx * headDim], cp, pp);
    qIn.EnQue(xUb);
    LocalTensor<T> xDq = qIn.DeQue<T>();

    // ---- Step 2: Cast x to float32 ----
    if constexpr (isHalf) {
        Cast(xFp32, xDq, RoundMode::CAST_NONE, headDim);
    } else {
        DataCopy(xFp32, xDq, headDim);
    }
    qIn.FreeTensor(xDq);

    // ---- Step 3: Multiply by scale ----
    if (scale != 1.0f) {
        Muls(xFp32, xFp32, scale, headDim);
    }

    // ---- Step 4: Copy mask[rowIdx, :] from GM to UB via qMask ----
    LocalTensor<float> mUb = qMask.AllocTensor<float>();
    DataCopyExtParams mcp{1, static_cast<uint32_t>(headDim * sizeof(float)), 0, 0, 0};
    DataCopyPadExtParams<float> mpad{false, 0, 0, 0};
    DataCopyPad(mUb, maskGm[rowIdx * headDim], mcp, mpad);
    qMask.EnQue(mUb);
    LocalTensor<float> mDq = qMask.DeQue<float>();
    DataCopy(maskUb, mDq, headDim);
    qMask.FreeTensor(mDq);

    // ---- Step 5: Apply mask ----
    // x = x * (1 - mask) + (-10000.0) * mask
    // 5a: tmp1 = x * mask
    Mul(tmp1Ub, xFp32, maskUb, headDim);
    // 5b: x = x - tmp1 = x * (1 - mask)
    Sub(xFp32, xFp32, tmp1Ub, headDim);
    // 5c: tmp1 = (-10000.0) * mask
    Muls(tmp1Ub, maskUb, -10000.0f, headDim);
    // 5d: x = x + tmp1 = x * (1-mask) + (-10000)*mask
    Add(xFp32, xFp32, tmp1Ub, headDim);

    // ---- Step 6: Softmax along head_dim ----
    // 6a: ReduceMax
    ReduceMax<float>(maxUb, xFp32, redTmp, static_cast<uint32_t>(reduceCount));
    float maxVal = maxUb.GetValue(0);

    // 6b: Subtract max
    Adds(subUb, xFp32, static_cast<float>(-maxVal), headDim);

    // 6c: Exp
    Exp(expUb, subUb, headDim);

    // 6d: ReduceSum
    ReduceSum<float>(sumUb, expUb, redTmp, static_cast<uint32_t>(reduceCount));
    float sumVal = sumUb.GetValue(0);

    // 6e: Normalize: softmax = exp / sum(exp)
    Muls(smUb, expUb, 1.0f / (sumVal + 1e-10f), headDim);

    // ---- Step 7: Cast softmax to original dtype + CopyOut via qOut ----
    LocalTensor<T> oT = qOut.AllocTensor<T>();
    if constexpr (isHalf) {
        Cast(oT, smUb, RoundMode::CAST_ROUND, headDim);
    } else {
        DataCopy(oT, smUb.ReinterpretCast<T>(), headDim);
    }
    qOut.EnQue(oT);
    LocalTensor<T> oD = qOut.DeQue<T>();
    DataCopyExtParams ocp{1, static_cast<uint32_t>(headDim * sizeof(T)), 0, 0, 0};
    DataCopyPad(yGm[rowIdx * headDim], oD, ocp);
    qOut.FreeTensor(oD);
}

// ============================================================================
// Kernel entry points
// ============================================================================
#define DEF_KERNEL_ENTRY(SUFFIX, TYPE)                                                 \
extern "C" __global__ __aicore__ void scaled_masked_softmax_v2_##SUFFIX(               \
    GM_ADDR x, GM_ADDR mask, GM_ADDR y,                                                \
    GM_ADDR tilingGM, GM_ADDR workspace)                                               \
{                                                                                      \
    auto* gmT = reinterpret_cast<__gm__ ScaledMaskedSoftmaxV2Tiling*>(tilingGM);      \
    ScaledMaskedSoftmaxV2Tiling t;                                                     \
    t.totalRows  = gmT->totalRows;                                                     \
    t.headDim    = gmT->headDim;                                                       \
    t.alignedHd  = gmT->alignedHd;                                                     \
    t.reduceCount = gmT->reduceCount;                                                  \
    t.coreNum    = gmT->coreNum;                                                       \
    t.rowsPerCore = gmT->rowsPerCore;                                                  \
    t.scale      = gmT->scale;                                                         \
    KernelScaledMaskedSoftmaxV2<TYPE> kernel;                                          \
    TPipe pipe;                                                                        \
    kernel.Init(x, mask, y, &t, &pipe);                                               \
    kernel.Process();                                                                  \
}

