91	    pipe->InitBuffer(qIn, 1, qInBytes);
92	
93	    // qMask: mask tile (type float, dedicated queue with proper float sizing)
94	    int64_t qMaskBytes = sizeof(float) * alignedHd + BLOCK_BYTES;
95	    pipe->InitBuffer(qMask, 1, qMaskBytes);
96	
97	    // qOut: output y tile (type T)
98	    int64_t qOutBytes = sizeof(T) * alignedHd + BLOCK_BYTES;
99	    pipe->InitBuffer(qOut, 1, qOutBytes);
100	
101	    // bufA: xFp32[alignedHd] + exp[alignedHd]
102	    pipe->InitBuffer(bufA, alignedHd * sizeof(float) * 2 + BLOCK_BYTES);
103	
104	    // bufB: mask[alignedHd] + tmp1[alignedHd] + sub[alignedHd] + softmax[alignedHd]
105	    pipe->InitBuffer(bufB, alignedHd * sizeof(float) * 4 + BLOCK_BYTES);
106	
107	    // bufC: reduceTmp[reduceCount*2*sizeof(float)] + max[1] + sum[1]
108	    int64_t redTmpBytes = reduceCount * sizeof(float) * 2;  // *2 required by ReduceMax/ReduceSum API
