120	template <typename T>
121	__aicore__ inline void KernelScaledMaskedSoftmaxV2<T>::ProcessRow(int64_t rowIdx)
122	{
123	    constexpr bool isHalf = (sizeof(T) == 2);
124	
125	    // UB buffer offsets
126	    LocalTensor<float> xFp32 = bufA.Get<float>(0);
127	    LocalTensor<float> expUb = bufA.Get<float>(alignedHd * sizeof(float));
128	
129	    LocalTensor<float> maskUb = bufB.Get<float>(0);
130	    LocalTensor<float> tmp1Ub = bufB.Get<float>(alignedHd * sizeof(float));
131	    LocalTensor<float> subUb  = bufB.Get<float>(alignedHd * sizeof(float) * 2);
132	    LocalTensor<float> smUb   = bufB.Get<float>(alignedHd * sizeof(float) * 3);
133	
134	    int64_t redTmpBytes = reduceCount * sizeof(float);
135	    LocalTensor<float> redTmp = bufC.Get<float>(0);
136	    LocalTensor<float> maxUb  = bufC.Get<float>(redTmpBytes);
137	    LocalTensor<float> sumUb  = bufC.Get<float>(redTmpBytes + sizeof(float));
138	
139	    // ---- Step 1: Copy input x[rowIdx, :] from GM to UB via qIn ----
140	    LocalTensor<T> xUb = qIn.AllocTensor<T>();
141	    DataCopyExtParams cp{1, static_cast<uint32_t>(headDim * sizeof(T)), 0, 0, 0};
142	    DataCopyPadExtParams<T> pp{false, 0, 0, 0};
143	    DataCopyPad(xUb, xGm[rowIdx * headDim], cp, pp);
144	    qIn.EnQue(xUb);
145	    LocalTensor<T> xDq = qIn.DeQue<T>();
146	
147	    // ---- Step 2: Cast x to float32 ----
148	    if constexpr (isHalf) {
149	        Cast(xFp32, xDq, RoundMode::CAST_NONE, headDim);
150	    } else {
151	        DataCopy(xFp32, xDq, headDim);
152	    }
153	    qIn.FreeTensor(xDq);
154	
155	    // ---- Step 3: Multiply by scale ----
156	    if (scale != 1.0f) {
157	        Muls(xFp32, xFp32, scale, headDim);
158	    }
159	
160	    // ---- Step 4: Copy mask[rowIdx, :] from GM to UB via dedicated qMask queue ----
161	    {
162	        LocalTensor<float> mUb = qMask.AllocTensor<float>();
163	        DataCopyExtParams mcp{1, static_cast<uint32_t>(headDim * sizeof(float)), 0, 0, 0};
164	        DataCopyPadExtParams<float> mpad{false, 0, 0, 0};
165	        DataCopyPad(mUb, maskGm[rowIdx * headDim], mcp, mpad);
166	        qMask.EnQue(mUb);
167	        LocalTensor<float> mDq = qMask.DeQue<float>();
168	        DataCopy(maskUb, mDq, headDim);
169	        qMask.FreeTensor(mDq);
170	    }
171	
172	    // ---- Step 5: Apply mask ----
173	    // x = x * (1 - mask) + (-10000.0) * mask
174	    // 5a: tmp1 = x * mask
175	    Mul(tmp1Ub, xFp32, maskUb, headDim);
176	    // 5b: x = x - tmp1 = x * (1 - mask)
177	    Sub(xFp32, xFp32, tmp1Ub, headDim);
178	    // 5c: tmp1 = (-10000.0) * mask
179	    Muls(tmp1Ub, maskUb, -10000.0f, headDim);
180	    // 5d: x = x + tmp1 = x * (1-mask) + (-10000)*mask
181	    Add(xFp32, xFp32, tmp1Ub, headDim);
182	
183	    // ---- Step 6: Softmax along head_dim ----
184	    // 6a: ReduceMax
185	    ReduceMax<float>(maxUb, xFp32, redTmp, static_cast<uint32_t>(reduceCount));
186	    float maxVal = maxUb.GetValue(0);
187	
188	    // 6b: Subtract max
189	    Adds(subUb, xFp32, static_cast<float>(-maxVal), headDim);
190	
191	    // 6c: Exp
192	    Exp(expUb, subUb, headDim);
193	
194	    // 6d: ReduceSum
195	    ReduceSum<float>(sumUb, expUb, redTmp, static_cast<uint32_t>(reduceCount));
196	    float sumVal = sumUb.GetValue(0);
197	
198	    // 6e: Normalize: softmax = exp / sum(exp)
199	    Muls(smUb, expUb, 1.0f / (sumVal + 1e-10f), headDim);
200	
201	    // ---- Step 7: Cast softmax to original dtype + CopyOut via qOut ----
202	    LocalTensor<T> oT = qOut.AllocTensor<T>();
203	    if constexpr (isHalf) {
204	        Cast(oT, smUb, RoundMode::CAST_ROUND, headDim);
205	    } else {
206	        DataCopy(oT, smUb.ReinterpretCast<T>(), headDim);
207	    }
208	    qOut.EnQue(oT);
209	    LocalTensor<T> oD = qOut.DeQue<T>();
210	    DataCopyExtParams ocp{1, static_cast<uint32_t>(headDim * sizeof(T)), 0, 0, 0};
211	    DataCopyPad(yGm[rowIdx * headDim], oD, ocp);
212	    qOut.FreeTensor(oD);
213	}
